### **🎮 "Avoid the Blocks" Game**
A simple reflex game where you control a square to avoid falling blocks. Press **Space** or **Arrow Keys** to move.

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Avoid the Blocks</title>
    <style>
        body {
            margin: 0;
            padding: 0;
            display: flex;
            justify-content: center;
            align-items: center;
            height: 100vh;
            background-color: #111;
            color: #fff;
            font-family: 'Arial', sans-serif;
            overflow: hidden;
        }
        #gameCanvas {
            border: 2px solid #444;
            background-color: #000;
        }
        #ui {
            position: absolute;
            top: 10px;
            left: 10px;
            font-size: 18px;
            color: #0f0;
        }
        #gameOver {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            text-align: center;
            display: none;
        }
        #gameOver h1 {
            font-size: 36px;
            color: #ff4444;
            margin: 0 0 10px 0;
        }
        #restartBtn {
            padding: 10px 20px;
            font-size: 18px;
            background-color: #444;
            color: #fff;
            border: none;
            cursor: pointer;
        }
        #restartBtn:hover {
            background-color: #666;
        }
    </style>
</head>
<body>
    <div id="ui">Score: <span id="score">0</span></div>
    <canvas id="gameCanvas" width="400" height="600"></canvas>
    <div id="gameOver">
        <h1>GAME OVER</h1>
        <p>Final Score: <span id="finalScore">0</span></p>
        <button id="restartBtn" onclick="restartGame()">Try Again</button>
    </div>

    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');
        const scoreElement = document.getElementById('score');
        const finalScoreElement = document.getElementById('finalScore');
        const gameOverScreen = document.getElementById('gameOver');

        let player = { x: 175, y: 500, width: 30, height: 30, speed: 5 };
        let blocks = [];
        let score = 0;
        let gameRunning = true;
        let blockSpeed = 3;
        let spawnRate = 60;
        let frameCount = 0;

        const keys = {};

        document.addEventListener('keydown', (e) => {
            keys[e.code] = true;
            if (e.code === 'Space' && !gameRunning && gameOverScreen.style.display === 'block') {
                restartGame();
            }
        });

        document.addEventListener('keyup', (e) => {
            keys[e.code] = false;
        });

        function spawnBlock() {
            const size = 30;
            const x = Math.random() * (canvas.width - size);
            blocks.push({ x, y: -size, width: size, height: size, speed: blockSpeed + Math.random() * 2 });
        }

        function update() {
            if (!gameRunning) return;

            if (keys['ArrowLeft'] && player.x > 0) player.x -= player.speed;
            if (keys['ArrowRight'] && player.x + player.width < canvas.width) player.x += player.speed;

            if (keys['ArrowUp'] && player.y > 0) player.y -= player.speed;
            if (keys['ArrowDown'] && player.y + player.height < canvas.height) player.y += player.speed;

            frameCount++;
            if (frameCount % spawnRate === 0) spawnBlock();

            blocks.forEach((block, index) => {
                block.y += block.speed;
                if (block.y > canvas.height) {
                    blocks.splice(index, 1);
                    score += 10;
                    scoreElement.textContent = score;
                    if (score % 100 === 0) blockSpeed += 0.5;
                }

                if (
                    player.x < block.x + block.width &&
                    player.x + player.width > block.x &&
                    player.y < block.y + block.height &&
                    player.y + player.height > block.y
                ) {
                    gameRunning = false;
                    finalScoreElement.textContent = score;
                    gameOverScreen.style.display = 'block';
                }
            });
        }

        function draw() {
            ctx.fillStyle = '#000';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            ctx.fillStyle = '#0f0';
            ctx.fillRect(player.x, player.y, player.width, player.height);

            blocks.forEach(block => {
                ctx.fillStyle = '#ff4444';
                ctx.fillRect(block.x, block.y, block.width, block.height);
            });
        }

        function gameLoop() {
            update();
            draw();
            if (gameRunning) {
                requestAnimationFrame(gameLoop);
            }
        }

        function restartGame() {
            player.x = 175;
            player.y = 500;
            blocks = [];
            score = 0;
            blockSpeed = 3;
            frameCount = 0;
            scoreElement.textContent = '0';
            gameOverScreen.style.display = 'none';
            gameRunning = true;
            gameLoop();
        }

        gameLoop();
    </script>
</body>
</html>
